(function(){'use strict';
const C=BusCore, KEY='busan-led-management-review-v1';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>[...root.querySelectorAll(q)];
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.schema!==1)state=C.seed();}catch{state=C.seed();}
let query='', currentPage='', selectedFile='', selectedFiles=new Set(), tablePage=1, busDraft=null, busSelected='', busDirty=false, modalCleanup=null;
const PAGE_SIZE=12;
const fileTypes={firmware:'펌웨어',route:'노선데이터',message:'메세지',image:'이미지',preview:'미리보기'};
const scopes={company:'운수사',route:'노선',vehicle:'차량'};
const scopeCols={company:'운수사',route:'노선번호',vehicle:'차량번호'};
const menus=[
 {id:'routes',label:'노선정보관리',items:[['route-company','운수사별 조회/적용'],['route-route','노선별 조회/적용'],['route-vehicle','차량별 조회/적용']]},
 {id:'messages',label:'메세지 관리',items:[['message-company','운수사별 조회/적용'],['message-route','노선별 조회/적용'],['message-vehicle','차량별 조회/적용']]},
 {id:'buses',label:'버스관리',items:[['bus-info','버스정보'],['device-status','단말기상태정보']]},
 {id:'files',label:'파일관리',items:Object.entries(fileTypes).map(([id,label])=>['file-'+id,label])},
 {id:'complaints',label:'민원관리',items:[['board-complaints','민원게시판']]},
 {id:'newbus',label:'신차출고요청관리',items:[['board-newbus','신차출고요청 게시판']]},
 {id:'maintenance',label:'유지보수관리',items:[['board-maintenance','유지보수신청 게시판'],['board-history','유지보수내역 관리']]},
 {id:'notice',label:'공지관리',items:[['board-notice','공지게시판']]},
 {id:'users',label:'사용자관리',items:[['users','사용자관리']]},
 {id:'companies',label:'운수사관리',items:[['companies','운수사관리']]}
];
let openGroups=new Set();
const nowDate=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'});
const file=id=>state.files.find(f=>f.id===id);
const fname=id=>file(id)?.title||'미설정';
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){throw Error('설정을 저장하지 못했습니다. 브라우저 저장 공간을 확인해 주세요.');}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3600);}
function options(items,value='',empty='선택'){return (empty===null?'':'<option value="">'+h(empty)+'</option>')+(value==='__mixed'?'<option value="__mixed" selected disabled>혼합</option>':'')+items.map(([v,l])=>'<option value="'+h(v)+'"'+(String(v)===String(value)?' selected':'')+'>'+h(l)+'</option>').join('');}
function versionSelect(type,value,id='',extra='',batch=false){return '<select '+(id?'id="'+h(id)+'" ':'')+'aria-label="'+(extra.includes('future')?'미래버전':'현재버전')+'" class="row-version" '+extra+'>'+options(state.files.filter(f=>f.type===type).map(f=>[f.id,f.title]),value,batch?'변경 안 함':'선택')+(extra.includes('future')?'<option value="__clear">예약 해제</option>':'')+'</select>';}
function statusBadge(value){const cls=value==='처리완료'||value==='정상'?'good':value==='진행중'?'wait':value==='미확인'||value==='비정상'?'bad':'';return '<span class="badge '+cls+'">'+h(value||'—')+'</span>';}
function title(name,en='',trail=''){return '<div class="page-title"><h1>'+h(name)+(en?'<small>'+h(en)+'</small>':'')+'</h1><span class="breadcrumb">'+h(trail)+'</span></div>';}
function search(label,placeholder,count=''){return '<div class="searchbar"><span class="search-icon" aria-hidden="true">⌕</span><span>'+h(label)+'</span><input id="page-search" value="'+h(query)+'" placeholder="'+h(placeholder)+'" aria-label="'+h(label)+' 검색"><small>'+h(count)+'</small></div>';}
function filtered(items,fn){const q=query.trim().toLowerCase();return !q?items:items.filter(x=>String(fn(x)).toLowerCase().includes(q));}
function table(headers,body,classes=''){return '<div class="table-wrap"><table class="'+classes+'"><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div>';}
function emptyRow(n,msg='조회된 항목이 없습니다.'){return '<tr><td colspan="'+n+'" class="table-empty">'+h(msg)+'</td></tr>';}
function pagination(total){const pages=Math.max(1,Math.ceil(total/PAGE_SIZE));tablePage=Math.min(tablePage,pages);return '<div class="pagination">'+Array.from({length:pages},(_,i)=>'<button data-action="page" data-page="'+(i+1)+'" class="'+(tablePage===i+1?'':'off')+'" aria-label="'+(i+1)+'페이지">'+(i+1)+'</button>').join('')+'</div>';}
function openModal(name,body,footer='',large=false){closeModal();const root=$('#modal-root');root.innerHTML='<div class="modal-backdrop"><section class="modal '+(large?'large':'')+'" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-title"><span id="dialog-title">'+h(name)+'</span><button data-action="close-modal" aria-label="닫기">×</button></div><div class="modal-body"><div id="form-error" class="form-error" role="alert"></div>'+body+'</div>'+(footer?'<div class="modal-actions">'+footer+'</div>':'')+'</section></div>';setTimeout(()=>$('.modal input:not([type=file]), .modal textarea, .modal select, .modal-title button')?.focus(),50);}
function closeModal(){if(modalCleanup){modalCleanup();modalCleanup=null;}$('#modal-root').innerHTML='';}
function formError(e){const el=$('#form-error');if(el){el.textContent=e.message||String(e);el.classList.add('visible');}else toast(e.message||String(e));}
function confirmBox(name,body,action,button='적용'){openModal(name,'<div class="confirm-copy">'+h(body)+'</div>','<button class="secondary" data-action="close-modal">취소</button><button id="confirm-submit">'+h(button)+'</button>');$('#confirm-submit').onclick=async()=>{try{$('#confirm-submit').disabled=true;await action();closeModal();}catch(e){formError(e);if($('#confirm-submit'))$('#confirm-submit').disabled=false;}};}
async function db(){return new Promise((resolve,reject)=>{const req=indexedDB.open('busan-led-review-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('blobs');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function blobPut(id,value){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('blobs','readwrite');t.objectStore('blobs').put(value,id);t.oncomplete=()=>{d.close();resolve();};t.onerror=()=>{d.close();reject(Error('파일 저장에 실패했습니다.'));};});}
async function blobGet(id){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('blobs','readonly');const r=t.objectStore('blobs').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);t.oncomplete=()=>d.close();});}
async function blobDelete(id){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('blobs','readwrite');t.objectStore('blobs').delete(id);t.oncomplete=()=>{d.close();resolve();};t.onerror=()=>reject(t.error);});}
function renderShell(){
 const page=location.hash.slice(1)||'dashboard';currentPage=page;const active=menus.find(m=>m.items.some(i=>i[0]===page));if(active)openGroups.add(active.id);
 $('#app').innerHTML='<aside class="sidebar"><button class="brand" data-action="home" aria-label="메인 현황"><img src="assets/busan-association.png" alt="부산광역시버스운송사업조합"></button><nav class="nav-scroll" aria-label="주 메뉴">'+menus.map(m=>'<div class="nav-group"><button class="nav-head '+(active?.id===m.id?'active':'')+'" data-action="nav-toggle" data-id="'+m.id+'" aria-expanded="'+openGroups.has(m.id)+'">'+m.label+'<span>'+(openGroups.has(m.id)?'⌃':'⌄')+'</span></button>'+(openGroups.has(m.id)?'<div class="nav-children">'+m.items.map(([id,name])=>'<a href="#'+id+'"'+(id===page?' class="selected" aria-current="page"':'')+'>'+name+'</a>').join('')+'</div>':'')+'</div>').join('')+'</nav><div class="nav-foot">행선지안내기 통합관리프로그램</div></aside><header class="topbar"><button class="menu-toggle" data-action="mobile-menu" aria-label="메뉴 열기">☰</button><span class="clock" id="clock"></span><div class="top-right"><span class="demo-chip" title="예시 데이터는 현재 브라우저에 저장됩니다. 실제 서버 및 장비에는 전송되지 않습니다.">검토용 · 장비 전송 없음</span><span>슈퍼관리자(슈퍼관리자)</span><button data-action="logout">Log Out</button></div></header><main id="main"></main>';
 renderContent();updateClock();
}
function updateClock(){if($('#clock'))$('#clock').textContent=new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});}
function renderContent(){const m=$('#main');if(!m)return;
 if(currentPage.startsWith('route-'))m.innerHTML=renderApply('route',currentPage.slice(6));
 else if(currentPage.startsWith('message-'))m.innerHTML=renderApply('message',currentPage.slice(8));
 else if(currentPage.startsWith('file-'))m.innerHTML=renderFiles(currentPage.slice(5));
 else if(currentPage==='bus-info')m.innerHTML=renderBus();
 else if(currentPage==='device-status')m.innerHTML=renderDevices();
 else if(currentPage.startsWith('board-'))m.innerHTML=renderBoard(currentPage.slice(6));
 else if(currentPage==='users'||currentPage==='companies')m.innerHTML=renderMaster(currentPage);
 else m.innerHTML=renderDashboard();
 if(currentPage.startsWith('route-')||currentPage.startsWith('message-'))previewInto(selectedFile);
}
function redrawWithFocus(){const input=$('#page-search'),pos=input?.selectionStart;renderContent();const next=$('#page-search');if(next){next.focus();next.setSelectionRange(pos,pos);}}
function routeTo(id){if(busDirty&&currentPage==='bus-info'){confirmBox('저장하지 않은 버스정보','편집한 내용을 저장하지 않고 이동하시겠습니까?',()=>{busDirty=false;busDraft=null;location.hash=id;},'이동');return;}location.hash=id;}
function renderApply(kind,scope){if(!scopes[scope])return '';const isRoute=kind==='route',type=isRoute?'route':'message',map=isRoute?state.routeSettings:state.messageSettings,all=C.groups(state,scope),list=filtered(all,g=>g.name+' '+(g.sub||''));const count=list.reduce((n,g)=>n+g.ids.length,0);const fields=isRoute?'<label>현재버전'+versionSelect('route','','bulk-current','data-field="current"',true)+'</label><label>미래버전'+versionSelect('route','','bulk-future','data-field="future"',true)+'</label><label class="wide">미래버전 적용일시<input id="bulk-at" type="datetime-local" aria-label="일괄 미래버전 적용일시"></label>':'<label class="wide">메세지<select id="bulk-message">'+options(state.files.filter(f=>f.type==='message').map(f=>[f.id,f.title]),'','변경 안 함')+'</select></label><label>적용 상태<select id="bulk-enabled">'+options([['true','적용'],['false','미적용']],'','변경 안 함')+'</select></label>';
 const rows=list.map((g,i)=>{const current=C.aggregate(map,g.ids,isRoute?'current':'message');const future=C.aggregate(map,g.ids,'future');const at=C.aggregate(map,g.ids,'at');const enabled=C.aggregate(map,g.ids,'enabled');return '<tr data-group="'+h(g.key)+'"><td><button class="link" data-action="group-preview" data-file="'+h(current==='__mixed'?'':current)+'">'+h(g.name)+'</button></td>'+(scope==='vehicle'&&isRoute?'<td>'+h(g.sub)+'</td>':'')+(isRoute?'<td>'+versionSelect('route',current,'','data-field="current"')+'</td><td>'+versionSelect('route',future,'','data-field="future"')+'</td><td><input class="row-date" data-field="at" type="datetime-local" aria-label="'+h(g.name)+' 미래버전 적용일시" value="'+h(at==='__mixed'?'':at)+'"></td>':'<td><select class="message-select" data-field="message" aria-label="'+h(g.name)+' 메세지">'+options(state.files.filter(f=>f.type==='message').map(f=>[f.id,f.title]),current,'선택')+'</select></td><td><select class="state-select" data-field="enabled" aria-label="'+h(g.name)+' 적용 상태">'+options([['true','적용'],['false','미적용']],String(enabled),enabled==='__mixed'?null:'선택')+'</select></td>')+'</tr>';}).join('');
 const headers=[scopeCols[scope],...(scope==='vehicle'&&isRoute?['노선번호']:[]),...(isRoute?['현재버전','미래버전','미래버전 적용일시']:['메세지','적용 상태'])];
 return title(scopes[scope]+'별 조회/적용',isRoute?'Route Management':'Message Management',(isRoute?'노선정보관리':'메세지 관리')+' / '+scopes[scope]+'별 조회/적용')+'<div class="split"><div>'+search(scopeCols[scope],scopeCols[scope]+' 검색',list.length+'개 대상')+'<section class="panel bulk"><div class="bulk-fields">'+fields+'<button data-action="apply-bulk" data-kind="'+kind+'" data-scope="'+scope+'">전체적용</button></div><div class="scope-note">현재 검색 결과 '+list.length+'개 '+scopes[scope]+' · '+count+'대에 적용</div></section><section class="panel"><div class="panel-bar"><span>'+scopes[scope]+'목록 <small>'+list.length+'개</small></span><button data-action="apply-rows" data-kind="'+kind+'" data-scope="'+scope+'">적용</button></div>'+table(headers,rows||emptyRow(headers.length),'compact apply-table')+'</section><p class="hint">'+(isRoute?'노선데이터':'메세지')+' 등록은 <a href="#file-'+type+'">파일관리 &gt; '+fileTypes[type]+'</a>에서 진행합니다.</p></div><section class="panel preview-panel" id="apply-preview"><div class="empty">'+(isRoute?'버전':'메세지')+'을 선택하면 등록된 내용을 확인할 수 있습니다.</div></section></div><div class="screen-note">검토용 적용 설정을 저장합니다. 실제 전송 및 예약 실행은 서버 연동이 필요합니다.</div>';
}
function previewHTML(f){if(!f)return '<div class="empty">항목을 선택하면 등록된 내용을 확인할 수 있습니다.</div>';let inner='';if(f.type==='route'){inner=f.rows?table(f.columns.map(h),f.rows.map(r=>'<tr>'+f.columns.map(c=>'<td title="'+h(r[c])+'">'+h(r[c])+'</td>').join('')+'</tr>').join(''),'data blue'):f.text?'<pre class="text-preview">'+h(f.text)+'</pre>':'<div class="empty">등록된 원본 파일을 다운로드하여 확인할 수 있습니다.</div>';}else if(f.type==='message'){inner='<div class="led" style="color:'+h(/^#[0-9a-f]{6}$/i.test(f.color)?f.color:'#ffdf44')+'">'+h(f.text)+'</div><div class="message-detail">'+h(f.name)+'<br>메세지 내용은 파일관리에서 등록한 값을 사용합니다.</div>';}else inner='<div class="empty">'+h(f.name)+'<br>등록된 파일을 선택해 확인하세요.</div>';return '<div class="preview-head"><span>'+h(f.title)+'</span><small>등록내용 미리보기</small></div>'+inner;}
function previewInto(id){const target=$('#apply-preview');if(target)target.innerHTML=previewHTML(file(id));}
function visibleGroups(scope){return filtered(C.groups(state,scope),g=>g.name+' '+(g.sub||''));}
function readChanges(root,isRoute){return isRoute?{current:$('[data-field=current]',root)?.value||'',future:$('[data-field=future]',root)?.value||'',at:$('[data-field=at]',root)?.value||''}:{message:$('[data-field=message]',root)?.value||'',enabled:$('[data-field=enabled]',root)?.value};}
function applySettings(kind,scope,bulk){
 const isRoute=kind==='route';const groups=visibleGroups(scope);let changes=[];
 if(bulk){const change=isRoute?{current:$('#bulk-current').value,future:$('#bulk-future').value,at:$('#bulk-at').value}:{message:$('#bulk-message').value,enabled:$('#bulk-enabled').value};if(isRoute?!change.current&&!change.future:!change.message&&!change.enabled)throw Error('적용할 항목을 선택해 주세요.');changes=[{ids:groups.flatMap(g=>g.ids),change}];}
 else changes=$$('.apply-table tbody tr[data-dirty="true"]').map(tr=>({ids:groups.find(g=>g.key===tr.dataset.group)?.ids||[],change:readChanges(tr,isRoute)}));
 if(!changes.length||!changes.some(c=>c.ids.length))throw Error('변경한 항목이 없습니다.');
 const next=C.clone(state);changes.forEach(({ids,change})=>{if(isRoute)C.applyVersions(next,'routeSettings',ids,change);else C.applyMessages(next,ids,change.message==='__mixed'?'':change.message,change.enabled==='true'?true:change.enabled==='false'?false:undefined);});
 const n=new Set(changes.flatMap(c=>c.ids)).size;
 confirmBox((isRoute?'노선정보':'메세지')+' 적용',n+'대의 '+(isRoute?'노선정보':'메세지')+' 설정을 저장합니다.\n다른 조회 메뉴에도 같은 차량의 설정이 반영됩니다.',()=>{state=next;persist();renderContent();toast(n+'대 적용 설정을 저장했습니다.');});
}
function renderFiles(type){if(!fileTypes[type])return '';const rows=filtered(state.files.filter(f=>f.type===type),f=>f.title+' '+f.name).slice().reverse();const pages=pagination(rows.length);const shown=rows.slice((tablePage-1)*PAGE_SIZE,tablePage*PAGE_SIZE);return title('파일관리 '+fileTypes[type],'File Management','파일관리 / '+fileTypes[type])+search('파일제목 / 파일명','검색어를 입력해 주세요.',rows.length+'건')+'<section class="panel">'+table(['<input type="checkbox" id="files-all" aria-label="현재 페이지 전체 선택">','번호','파일제목','파일명','파일타입','등록날짜','삭제'],shown.map((f,i)=>'<tr><td><input type="checkbox" data-file-check="'+h(f.id)+'" '+(selectedFiles.has(f.id)?'checked':'')+' aria-label="'+h(f.title)+' 선택"></td><td>'+(rows.length-(tablePage-1)*PAGE_SIZE-i)+'</td><td><button class="link" data-action="file-detail" data-id="'+h(f.id)+'">'+h(f.title)+'</button></td><td><button class="link" data-action="file-download" data-id="'+h(f.id)+'">'+h(f.name)+'</button></td><td>'+fileTypes[type]+'</td><td>'+h(f.date)+'</td><td><button class="danger small" data-action="file-delete" data-id="'+h(f.id)+'">삭제</button></td></tr>').join('')||emptyRow(7))+'</section><div class="file-actions"><span class="selected-count" id="selected-files-count">선택 '+selectedFiles.size+'건</span>'+pages+'<button data-action="file-register" data-type="'+type+'">＋ 파일등록</button></div>';
}
async function registerFile(type){
 const isMsg=type==='message';let body='<div class="form-grid"><div class="field full"><label for="file-title">파일제목'+(type==='route'||type==='firmware'?' / 버전':'')+' *</label><input id="file-title" placeholder="'+(type==='route'?'예: bsh_261112':type==='firmware'?'예: R11065':'파일제목을 입력해 주세요.')+'" maxlength="100"></div>';
 if(isMsg)body+='<div class="field full"><label for="message-text">메세지 *</label><textarea id="message-text" placeholder="전광판에 표출할 메세지를 입력해 주세요."></textarea></div><div class="field"><label for="message-color">표출 색상</label><input id="message-color" type="color" value="#ffdf44"></div><div class="field"><label for="message-name">파일명</label><input id="message-name" value="message_'+nowDate().replaceAll('-','')+'.json"></div><div class="field full upload-box"><label for="file-input">기존 메세지 불러오기 (선택)</label><input id="file-input" type="file" accept=".json,.txt"><span class="hint">JSON: text, color 항목 / TXT: 메세지 본문</span></div><div class="field full"><div class="led no-margin" id="message-live">메세지 미리보기</div></div>';
 else body+='<div class="field full upload-box"><label for="file-input">파일 선택 *</label><input id="file-input" type="file" '+(type==='image'?'accept="image/*"':'')+'><span class="hint">'+(type==='route'?'XLSX·CSV·TSV·JSON·TXT는 내용 미리보기를 지원합니다. ZIP·BIN 등 다른 형식은 원본 파일로 등록합니다.':type==='image'?'이미지 원본을 등록합니다.':'원본 파일을 등록합니다.')+'</span></div>';
 if(type==='route')body+='<div class="field full"><button class="secondary" id="route-template">노선데이터 엑셀 양식 다운로드</button></div>';
 body+='</div>';openModal(fileTypes[type]+' 파일등록',body,'<button class="secondary" data-action="close-modal">취소</button><button id="register-submit">등록</button>');
 if(type==='route')$('#route-template').onclick=async()=>ExcelIO.download(await ExcelIO.blob(C.ROUTE_COLUMNS,[]),'노선데이터_양식.xlsx');
 if(isMsg){const update=()=>{$('#message-live').textContent=$('#message-text').value||'메세지 미리보기';$('#message-live').style.color=$('#message-color').value;};$('#message-text').oninput=update;$('#message-color').oninput=update;$('#file-input').onchange=async()=>{try{const f=$('#file-input').files[0];if(!f)return;const text=await f.text();if(/\.json$/i.test(f.name)){const m=JSON.parse(text);if(typeof m.text!=='string')throw Error('JSON 파일에 text 항목이 필요합니다.');$('#message-text').value=m.text;if(/^#[\da-f]{6}$/i.test(m.color))$('#message-color').value=m.color;}else $('#message-text').value=text;$('#message-name').value=f.name.replace(/\.[^.]+$/,'.json');update();}catch(e){formError(e);}};}
 $('#register-submit').onclick=async()=>{const btn=$('#register-submit');btn.disabled=true;try{const name=$('#file-title').value.trim();if(!name)throw Error('파일제목을 입력해 주세요.');if(state.files.some(f=>f.type===type&&f.title===name))throw Error('같은 제목의 파일이 있습니다. 다른 제목 또는 버전을 입력해 주세요.');let f={id:C.uid(),type,title:name,date:nowDate(),size:0};let blob;
 if(isMsg){f.text=$('#message-text').value.trim();if(!f.text)throw Error('메세지를 입력해 주세요.');f.color=$('#message-color').value;f.name=$('#message-name').value.trim()||'message.json';if(!/\.json$/i.test(f.name))f.name+='.json';blob=new Blob([JSON.stringify({text:f.text,color:f.color},null,2)],{type:'application/json'});}
 else{const upload=$('#file-input').files[0];if(!upload)throw Error('파일을 선택해 주세요.');if(upload.size>50*1024*1024)throw Error('검토용 화면은 파일당 최대 50MB까지 등록할 수 있습니다.');f.name=upload.name;f.mime=upload.type;blob=upload;
 if(type==='image'&&!upload.type.startsWith('image/'))throw Error('이미지 파일을 선택해 주세요.');
 if(type==='route'){if(/\.(xlsx|csv|tsv)$/i.test(upload.name)){const data=await ExcelIO.read(upload);if(!data.rows.length)throw Error('노선데이터가 비어 있습니다.');f={...f,...data};}else if(/\.json$/i.test(upload.name)){const data=JSON.parse(await upload.text());if(Array.isArray(data)){if(!data.length||!data.every(r=>r&&typeof r==='object'&&!Array.isArray(r)))throw Error('노선 JSON은 객체 배열이어야 합니다.');f.rows=data;f.columns=[...new Set(data.flatMap(Object.keys))];}else if(Array.isArray(data.rows)&&Array.isArray(data.columns)){f.rows=data.rows;f.columns=data.columns;}else throw Error('JSON은 행 배열 또는 columns/rows 구조여야 합니다.');}else if(/\.txt$/i.test(upload.name))f.text=await upload.text();}}
 f.size=blob.size;await blobPut(f.id,blob);state.files.push(f);try{persist();}catch(e){state.files.pop();await blobDelete(f.id);throw e;}closeModal();renderContent();toast('파일을 등록했습니다.');}catch(e){formError(e);btn.disabled=false;}};
}
async function downloadFile(id){const f=file(id);if(!f)return;let blob=await blobGet(id);if(!blob){if(f.rows)blob=await ExcelIO.blob(f.columns,f.rows);else if(f.type==='message')blob=new Blob([JSON.stringify({text:f.text,color:f.color},null,2)],{type:'application/json'});else throw Error('예시 파일에는 실제 펌웨어 바이너리가 없습니다. 파일등록에서 원본 파일을 등록해 주세요.');}ExcelIO.download(blob,f.name);}
async function fileDetail(id){const f=file(id);if(!f)return;openModal(f.title,'<div class="file-meta"><span>파일명 <strong>'+h(f.name)+'</strong></span><span>파일타입 <strong>'+h(fileTypes[f.type])+'</strong></span><span>등록날짜 <strong>'+h(f.date)+'</strong></span></div><div id="file-detail-content">'+previewHTML(f)+'</div>','<button class="secondary" data-action="close-modal">닫기</button><button data-action="file-download" data-id="'+h(id)+'">다운로드</button>',true);
 if(['image','preview'].includes(f.type)){const blob=await blobGet(id);if(!blob)return;if(blob.type.startsWith('image/')){const url=URL.createObjectURL(blob);$('#file-detail-content').innerHTML='<img class="preview-image" src="'+url+'" alt="'+h(f.title)+'">';modalCleanup=()=>URL.revokeObjectURL(url);}else if(blob.type.startsWith('text/')||/\.(txt|json|html|csv)$/i.test(f.name))$('#file-detail-content').innerHTML='<pre class="text-preview">'+h((await blob.text()).slice(0,100000))+'</pre>';}
}
function deleteFile(id){const f=file(id);if(!f)return;if(C.references(state,id))throw Error('현재 적용 또는 예약에 사용 중인 파일입니다. 해당 설정을 변경한 뒤 삭제해 주세요.');confirmBox('파일 삭제',f.title+' 파일을 삭제하시겠습니까?',async()=>{await blobDelete(id);state.files=state.files.filter(x=>x.id!==id);selectedFiles.delete(id);persist();renderContent();toast('파일을 삭제했습니다.');},'삭제');}
function ensureBusDraft(){if(!busDraft){const version=state.busVersions.find(v=>v.id===state.activeBusVersion)||state.busVersions[0];busDraft=C.clone(version);busDirty=false;}}
function markBusDirty(){busDirty=true;const el=$('#bus-dirty');if(el)el.textContent='저장하지 않은 변경사항';}
function renderBus(){ensureBusDraft();const rows=filtered(busDraft.rows,r=>r['차량번호']);return title('버스정보','BUS Management','버스관리 / 버스정보')+'<div class="toolbar editor-toolbar"><div class="group"><button data-action="bus-copy">행복사</button><button data-action="bus-add">행추가</button><button data-action="bus-column">열추가</button><button class="danger solid" data-action="bus-delete">삭제</button></div><div class="group"><button class="secondary" data-action="bus-import">▦ 엑셀 불러오기</button><button class="secondary" data-action="bus-export">엑셀 저장</button><label>버전선택 <select id="bus-version">'+options(state.busVersions.map(v=>[v.id,v.title]),busDraft.id,null)+'</select></label><label>버전입력 <input id="bus-version-name" value="'+h(busDraft.title)+'" style="width:135px" aria-label="버스정보 버전입력"></label><button data-action="bus-save">저장</button></div></div>'+search('차량번호','차량번호 검색',rows.length+'대')+'<section class="panel">'+table(['선택','번호',...busDraft.columns.map(h),'삭제'],rows.map((r,i)=>'<tr class="'+(busSelected===r.id?'selected':'')+'" data-bus-id="'+h(r.id)+'"><td><input type="radio" name="bus-row" value="'+h(r.id)+'" '+(busSelected===r.id?'checked':'')+' aria-label="'+h(r['차량번호']||'새 행')+' 선택"></td><td>'+(busDraft.rows.indexOf(r)+1)+'</td>'+busDraft.columns.map(c=>'<td>'+(['전면','측면'].includes(c)?'<select data-bus-column="'+h(c)+'" aria-label="'+h(c)+'">'+options((c==='전면'?['미설치','전면']:['미설치','측면일반','측면특수']).map(x=>[x,x]),r[c],'선택')+'</select>':'<input '+(['차대등록일','차량만료일'].includes(c)?'type="date"':'type="text"')+' data-bus-column="'+h(c)+'" aria-label="'+h(c)+'" value="'+h(r[c])+'">')+'</td>').join('')+'<td><button class="danger small" data-action="bus-delete" data-id="'+h(r.id)+'">삭제</button></td></tr>').join('')||emptyRow(busDraft.columns.length+3),'blue editor-table')+'</section><div class="editor-footer"><span>총 '+busDraft.rows.length+'대 · '+busDraft.columns.length+'개 열</span><span id="bus-dirty" class="pending-mark">'+(busDirty?'저장하지 않은 변경사항':'')+'</span></div>';
}
function addBus(copy){ensureBusDraft();let row;if(copy){const selected=busDraft.rows.find(r=>r.id===busSelected);if(!selected)throw Error('복사할 행을 선택해 주세요.');row={...C.clone(selected),id:C.uid(),'차량번호':''};const idx=busDraft.rows.indexOf(selected);busDraft.rows.splice(idx+1,0,row);}else{row={id:C.uid(),...Object.fromEntries(busDraft.columns.map(c=>[c,'']))};busDraft.rows.push(row);}query='';busSelected=row.id;markBusDirty();renderContent();const input=$$('tr[data-bus-id]').find(tr=>tr.dataset.busId===row.id)?.querySelector('input[data-bus-column="차량번호"]');input?.scrollIntoView({block:'center'});input?.focus();}
function addBusColumn(){openModal('열추가','<div class="field"><label for="column-name">추가할 열 이름</label><input id="column-name" placeholder="예: 비고"></div>','<button class="secondary" data-action="close-modal">취소</button><button id="column-submit">추가</button>');$('#column-submit').onclick=()=>{try{const name=$('#column-name').value.trim();if(!name)throw Error('열 이름을 입력해 주세요.');if(['id','__proto__','constructor','prototype'].includes(name)||busDraft.columns.includes(name))throw Error('이미 존재하거나 사용할 수 없는 열 이름입니다.');busDraft.columns.push(name);busDraft.rows.forEach(r=>r[name]='');markBusDirty();closeModal();renderContent();}catch(e){formError(e);}};}
function deleteBus(id){const key=id||busSelected;if(!key)throw Error('삭제할 행을 선택해 주세요.');const row=busDraft.rows.find(r=>r.id===key);if(!row)return;confirmBox('행 삭제',(row['차량번호']||'선택한 행')+'을 편집 목록에서 삭제합니다. 버전을 저장하면 반영됩니다.',()=>{busDraft.rows=busDraft.rows.filter(r=>r.id!==key);busSelected='';markBusDirty();renderContent();},'삭제');}
function saveBus(){busDraft.title=$('#bus-version-name').value.trim();if(!busDraft.title)throw Error('버전명을 입력해 주세요.');busDraft.rows.forEach(r=>r['차량번호']=String(r['차량번호']||'').trim());C.validateBuses(busDraft.rows);const existing=state.busVersions.find(v=>v.title===busDraft.title);const commit=()=>{const saved={...C.clone(busDraft),id:existing?.id||C.uid()};if(existing)state.busVersions[state.busVersions.indexOf(existing)]=saved;else state.busVersions.push(saved);state.buses=C.clone(saved.rows);state.busColumns=[...saved.columns];state.activeBusVersion=saved.id;state.buses.forEach(b=>{if(!state.routeSettings[b.id])state.routeSettings[b.id]={current:'',future:'',at:''};if(!state.messageSettings[b.id])state.messageSettings[b.id]={message:'',enabled:false};});persist();busDraft=C.clone(saved);busDirty=false;renderContent();toast('버스정보 버전을 저장했습니다.');};if(existing)confirmBox('버스정보 저장','기존 '+existing.title+' 버전을 수정하고 현재 버스정보에 반영합니다.',commit,'저장');else commit();}
function changeBusVersion(id){const change=()=>{busDraft=C.clone(state.busVersions.find(v=>v.id===id));busDirty=false;busSelected='';query='';renderContent();};if(busDirty)confirmBox('버전 변경','저장하지 않은 편집 내용을 버리고 선택한 버전을 불러오시겠습니까?',change,'불러오기');else change();}
async function importBuses(upload){if(!upload)return;if(upload.size>50*1024*1024)throw Error('엑셀 파일은 최대 50MB까지 불러올 수 있습니다.');const parsed=await ExcelIO.read(upload);const required=['운수사','인가노선','차량번호'];if(required.some(c=>!parsed.columns.includes(c)))throw Error('엑셀 첫 행에 운수사, 인가노선, 차량번호 열이 필요합니다.');if(parsed.columns.some(c=>['id','__proto__','constructor','prototype'].includes(c)))throw Error('엑셀에 사용할 수 없는 열 이름이 있습니다.');const rows=parsed.rows.filter(r=>Object.values(r).some(Boolean)).map(r=>({...r,'차량번호':String(r['차량번호']||'').trim()}));const columns=[...new Set([...C.BUS_COLUMNS,...parsed.columns])];const mapped=rows.map(r=>({...Object.fromEntries(columns.map(c=>[c,r[c]||''])),id:state.buses.find(b=>b['차량번호']===r['차량번호'])?.id||C.uid()}));C.validateBuses(mapped);confirmBox('엑셀 불러오기',mapped.length+'대의 버스정보를 편집 목록에 불러옵니다.\n현재 편집 목록을 대체하며, 저장 버튼을 눌러야 버전에 반영됩니다.',()=>{busDraft.columns=columns;busDraft.rows=mapped;busSelected='';query='';markBusDirty();renderContent();toast(mapped.length+'대를 불러왔습니다.');},'불러오기');}
function deviceRows(){return state.devices.filter(d=>state.buses.some(b=>b.id===d.busId)).filter(d=>{const b=state.buses.find(b=>b.id===d.busId);const q=query.toLowerCase();return !q||[b['인가노선'],b['차량번호'],d.mac].some(x=>String(x).toLowerCase().includes(q));});}
function renderDevices(){const rows=deviceRows();return title('단말기상태정보','Device Management','버스관리 / 단말기상태정보')+'<div class="toolbar device-toolbar"><section class="panel bulk no-margin device-bulk"><div class="bulk-fields"><label>펌웨어 현재버전'+versionSelect('firmware','','device-current','data-field="current"',true)+'</label><label>펌웨어 미래버전'+versionSelect('firmware','','device-future','data-field="future"',true)+'</label><label class="device-schedule-field">펌웨어 미래버전 적용일시<input type="datetime-local" id="device-at"></label><button data-action="device-bulk">전체적용</button></div></section><span class="spacer"></span><button class="secondary" data-action="device-export">▦ 저장</button><button data-action="device-apply">적용</button></div>'+search('노선번호 / 차량번호 / MAC','노선번호, 차량번호 또는 MAC 검색',rows.length+'개 단말')+'<section class="panel">'+table(['번호','단말기<br>위치','운수사명','차량번호','노선ID','노선<br>번호','운행상태','상행/<br>하행','정류장<br>순번','잔여좌석<br>사용여부','단말기<br>오류','커널<br>버전','현재노선<br>버전','미래노선<br>버전','펌웨어<br>실제버전','펌웨어<br>현재버전','펌웨어<br>미래버전','펌웨어<br>미래버전 적용일시','업데이트<br>시간','등록일','단말기 MAC','삭제'],rows.map((d,i)=>{const b=state.buses.find(b=>b.id===d.busId),r=state.routeSettings[b.id]||{},f=state.firmwareSettings[d.id]||{};return '<tr data-device="'+h(d.id)+'"><td>'+(rows.length-i)+'</td><td>'+h(d.position)+'</td><td>'+h(b['운수사'])+'</td><td>'+h(b['차량번호'])+'</td><td>'+h('260'+String(1002+Number(b.id.replace('b','')||0)))+'</td><td>'+h(b['인가노선'])+'</td><td>운행대기</td><td>'+d.direction+'</td><td>'+d.stop+'</td><td>미사용</td><td>'+statusBadge(d.state)+'</td><td>'+d.kernel+'</td><td>'+h(fname(r.current))+'</td><td>'+h(r.future?fname(r.future):'—')+'</td><td>'+h(fname(d.actual))+'</td><td>'+versionSelect('firmware',f.current,'','data-field="current"')+'</td><td>'+versionSelect('firmware',f.future,'','data-field="future"')+'</td><td><input class="row-date" type="datetime-local" value="'+h(f.at)+'" data-field="at" aria-label="펌웨어 미래버전 적용일시"></td><td>'+h(d.last)+'</td><td>'+h(d.registered)+'</td><td>'+h(d.mac)+'</td><td><button class="danger small" data-action="device-delete" data-id="'+h(d.id)+'">삭제</button></td></tr>';}).join('')||emptyRow(22),'blue data compact status-table')+'</section><p class="screen-note">실제버전은 예시 수신값입니다. 적용 설정을 변경해도 실제버전이 변경되지는 않습니다.</p>';}
function applyDevices(bulk){const changes=bulk?[{ids:deviceRows().map(d=>d.id),change:{current:$('#device-current').value,future:$('#device-future').value,at:$('#device-at').value}}]:$$('tr[data-device][data-dirty="true"]').map(tr=>({ids:[tr.dataset.device],change:readChanges(tr,true)}));if(!changes.length||!changes.some(x=>x.ids.length))throw Error('변경할 단말기가 없습니다.');if(bulk&&!changes[0].change.current&&!changes[0].change.future)throw Error('적용할 버전을 선택해 주세요.');const next=C.clone(state);changes.forEach(x=>C.applyVersions(next,'firmwareSettings',x.ids,x.change));const n=changes.reduce((sum,x)=>sum+x.ids.length,0);confirmBox('펌웨어 적용',n+'개 단말기의 적용 설정을 저장합니다.',()=>{state=next;persist();renderContent();toast(n+'개 단말기의 설정을 저장했습니다.');});}
const boardInfo={complaints:['민원게시판','Minwon Management'],newbus:['신차출고요청 게시판','New car delivery request Management'],maintenance:['유지보수신청 게시판','Maintenance request Management'],history:['유지보수내역 관리','Maintenance History Management'],notice:['공지게시판','Notice Management']};
function renderBoard(key){const info=boardInfo[key];if(!info)return '';const hasStatus=['newbus','maintenance'].includes(key),history=key==='history';const list=filtered(state.boards[key],p=>p.title).slice().reverse();const pages=pagination(list.length);const shown=list.slice((tablePage-1)*PAGE_SIZE,tablePage*PAGE_SIZE);const headers=history?['번호','제목','문서종류','작성자','수정날짜']:['번호','제목','첨부파일','작성자',...(key==='notice'?[]:['운수사명']),...(hasStatus?['처리상태']:[]),'등록날짜'];return title(info[0],info[1])+search('제목','검색어를 입력해 주세요.',list.length+'건')+'<section class="panel">'+table(headers,shown.map((p,i)=>'<tr><td>'+(key==='notice'?'공지':list.length-(tablePage-1)*PAGE_SIZE-i)+'</td><td><button class="link" data-action="post-detail" data-board="'+key+'" data-id="'+h(p.id)+'">'+h(p.title)+'</button></td>'+(history?'<td>'+h(p.docType)+'</td>':'<td>'+h(p.attachment||'')+'</td>')+'<td>'+h(p.author)+'</td>'+(!history&&key!=='notice'?'<td>'+h(p.company)+'</td>':'')+(hasStatus?'<td>'+statusBadge(p.status)+'</td>':'')+'<td>'+h(p.date)+'</td></tr>').join('')||emptyRow(headers.length))+'</section><div class="file-actions"><span></span>'+pages+'<button data-action="post-new" data-board="'+key+'">✎ 등록</button></div>';}
function postDetail(key,id){const p=state.boards[key].find(x=>x.id===id);if(!p)return;openModal(p.title,'<div class="post-meta"><span>작성자 '+h(p.author)+'</span><span>운수사 '+h(p.company||'—')+'</span><span>등록일 '+h(p.date)+'</span>'+(p.status?statusBadge(p.status):'')+'</div><div class="post-body">'+h(p.body)+'</div>'+(p.attachment?'<button class="link attachment-link" data-action="post-download" data-id="'+h(p.id)+'" data-name="'+h(p.attachment)+'">첨부파일: '+h(p.attachment)+'</button>':''),'<button class="secondary" data-action="close-modal">닫기</button><button data-action="post-edit" data-board="'+key+'" data-id="'+h(id)+'">수정</button>');}
function postForm(key,id=''){const p=state.boards[key].find(x=>x.id===id)||{title:'',body:'',company:'',status:'미확인',docType:'A/S 접수 및 처리내역'};const hasStatus=['newbus','maintenance'].includes(key);openModal(boardInfo[key][0]+' '+(id?'수정':'등록'),'<div class="form-grid"><div class="field full"><label>제목 *</label><input id="post-title" value="'+h(p.title)+'"></div>'+(key!=='notice'?'<div class="field"><label>운수사</label><select id="post-company">'+options(state.companies.map(c=>[c.name,c.name]),p.company)+'</select></div>':'')+(hasStatus?'<div class="field"><label>처리상태</label><select id="post-status">'+options(['미확인','진행중','처리완료'].map(x=>[x,x]),p.status,null)+'</select></div>':'')+(key==='history'?'<div class="field"><label>문서종류</label><select id="post-doctype">'+options(['A/S 접수 및 처리내역','대·폐차 현황','기타'].map(x=>[x,x]),p.docType,null)+'</select></div>':'')+'<div class="field full"><label>내용 *</label><textarea id="post-body">'+h(p.body)+'</textarea></div><div class="field full"><label>첨부파일'+(p.attachment?' (현재: '+h(p.attachment)+')':'')+'</label><input id="post-file" type="file"></div></div>','<button class="secondary" data-action="close-modal">취소</button><button id="post-submit">저장</button>');$('#post-submit').onclick=async()=>{try{const title=$('#post-title').value.trim(),body=$('#post-body').value.trim();if(!title||!body)throw Error('제목과 내용을 입력해 주세요.');const row={...p,id:id||C.uid(),title,body,company:$('#post-company')?.value||'',status:$('#post-status')?.value||'',docType:$('#post-doctype')?.value||'',date:nowDate(),author:p.author||'관리자'};const upload=$('#post-file').files[0];if(upload){if(upload.size>50*1024*1024)throw Error('최대 50MB까지 첨부할 수 있습니다.');await blobPut('post-'+row.id,upload);row.attachment=upload.name;}if(id)state.boards[key][state.boards[key].findIndex(x=>x.id===id)]=row;else state.boards[key].push(row);persist();closeModal();renderContent();toast('게시글을 저장했습니다.');}catch(e){formError(e);}};}
function renderMaster(type){const users=type==='users';const list=filtered(users?state.users:state.companies,x=>users?x.login+' '+x.name:x.name).slice().reverse();const pages=pagination(list.length);const shown=list.slice((tablePage-1)*PAGE_SIZE,tablePage*PAGE_SIZE);return title(users?'사용자관리':'운수사관리',users?'User Management':'Bus Company Management')+search(users?'아이디 / 이름':'운수사명','검색어를 입력해 주세요.',list.length+'건')+'<section class="panel">'+table(['<input type="checkbox" id="master-all" aria-label="전체 선택">','번호',...(users?['아이디','이름','전화번호','직함','권한','운수사명','등록일']:['운수사명','전화번호','주소','등록일'])],shown.map((r,i)=>'<tr><td><input type="checkbox" data-master-check="'+h(r.id)+'" aria-label="'+h(r.name)+' 선택"></td><td>'+(list.length-(tablePage-1)*PAGE_SIZE-i)+'</td><td><button class="link" data-action="master-edit" data-type="'+type+'" data-id="'+h(r.id)+'">'+h(users?r.login:r.name)+'</button></td>'+(users?['name','phone','position','role','company','date']:['phone','address','date']).map(k=>'<td>'+h(r[k])+'</td>').join('')+'</tr>').join('')||emptyRow(users?9:6))+'</section><div class="file-actions"><button class="secondary" data-action="master-delete" data-type="'+type+'">삭제</button>'+pages+'<button data-action="master-edit" data-type="'+type+'">＋ '+(users?'사용자':'운수사')+'등록</button></div>';}
function masterForm(type,id=''){const users=type==='users';const list=users?state.users:state.companies;const r=list.find(x=>x.id===id)||{};const fields=users?[['login','아이디'],['name','이름'],['phone','전화번호'],['position','직함']]:[['name','운수사명'],['phone','전화번호'],['address','주소']];openModal((users?'사용자':'운수사')+(id?' 수정':' 등록'),'<div class="form-grid">'+fields.map(([key,label])=>'<div class="field"><label>'+label+'</label><input id="master-'+key+'" value="'+h(r[key])+'"></div>').join('')+(users?'<div class="field"><label>권한</label><select id="master-role">'+options(['슈퍼관리자','유지보수','운수사'].map(x=>[x,x]),r.role||'운수사',null)+'</select></div><div class="field"><label>운수사명</label><select id="master-company">'+options(state.companies.map(c=>[c.name,c.name]),r.company)+'</select></div>':'')+'</div>','<button class="secondary" data-action="close-modal">취소</button><button id="master-submit">저장</button>');$('#master-submit').onclick=()=>{try{const data=Object.fromEntries(fields.map(([k])=>[k,$('#master-'+k).value.trim()]));if(!data.name||(users&&!data.login))throw Error('이름'+(users?'과 아이디를':'을')+' 입력해 주세요.');if(list.some(x=>x.id!==id&&(users?x.login===data.login:x.name===data.name)))throw Error('같은 '+(users?'아이디':'운수사명')+'가 있습니다.');const row={...r,...data,id:id||C.uid(),date:r.date||nowDate(),...(users?{role:$('#master-role').value,company:$('#master-company').value}:{})};if(id){list[list.findIndex(x=>x.id===id)]=row;if(!users&&r.name!==row.name){state.buses.forEach(b=>{if(b['운수사']===r.name)b['운수사']=row.name;});state.users.forEach(u=>{if(u.company===r.name)u.company=row.name;});}}else list.push(row);persist();closeModal();renderContent();toast('정보를 저장했습니다.');}catch(e){formError(e);}};}
function renderDashboard(){const ds=state.devices.filter(d=>state.buses.some(b=>b.id===d.busId));const count=items=>({all:items.length,ok:items.filter(d=>d.state==='정상').length,bad:items.filter(d=>d.state!=='정상').length});const total=count(ds),front=count(ds.filter(d=>d.position==='전면')),side=count(ds.filter(d=>d.position!=='전면'));const numbers=items=>{const c=count(items);return '<span class="num-good">'+c.ok+'</span><span class="num-bad">'+c.bad+'</span>';};const companyRows=state.companies.map(c=>{const ids=state.buses.filter(b=>b['운수사']===c.name).map(b=>b.id);const devices=ds.filter(d=>ids.includes(d.busId));return '<tr><td>'+h(c.name)+'</td><td>'+numbers(devices)+'</td><td>'+numbers(devices.filter(d=>d.position==='전면'))+'</td><td>'+numbers(devices.filter(d=>d.position!=='전면'))+'</td></tr>';}).join('');const miniBoard=(key,name)=>'<div><div class="section-title"><span>'+name+'</span><button class="small" data-action="navigate" data-target="board-'+key+'">더보기</button></div><div class="panel dash-board">'+table(['번호','제목','작성자',...(key==='notice'?[]:['처리상태']),'등록일'],state.boards[key].slice().reverse().slice(0,6).map((p,i)=>'<tr><td>'+(key==='notice'?'공지':i+1)+'</td><td title="'+h(p.title)+'"><button class="link" data-action="post-detail" data-board="'+key+'" data-id="'+p.id+'">'+h(p.title)+'</button></td><td>'+h(p.author)+'</td>'+(key==='notice'?'':'<td>'+h(p.status)+'</td>')+'<td>'+h(p.date)+'</td></tr>').join(''))+'</div></div>';
 const msgRows=C.groups(state,'route').map(g=>{const id=C.aggregate(state.messageSettings,g.ids,'message');return '<tr><td>'+h(g.name)+'</td><td style="color:#ad65c5">'+h(id==='__mixed'?'혼합':file(id)?.text||'미설정')+'</td><td>2026-11-12</td></tr>';}).join('');
 return '<div class="dash-top"><div class="server-status"><span>서버상태</span><span class="status-dot"></span><span>검토용 예시 데이터</span><span class="muted">실제 서버 미연결</span></div><button class="small" data-action="navigate" data-target="device-status">단말기상태정보</button></div><div class="dash-grid"><section class="panel"><div class="stats">'+[['총 단말기 수',total],['총 전면 단말기 수',front],['총 측면 단말기 수',side]].map(([name,c])=>'<div class="stat-group"><div><div class="stat-label">'+name+'</div><span class="stat-number">'+c.all+'개</span></div><div><div class="stat-label good">정상</div><span class="stat-number">'+c.ok+'개</span></div><div><div class="stat-label bad">비정상</div><span class="stat-number">'+c.bad+'개</span></div></div>').join('')+'</div><div class="dash-panel">'+table(['운수사','전체','전면','측면'],companyRows)+'</div></section><div><div class="section-title">메세지 운영 현황</div><div class="panel dash-message">'+table(['노선번호','메세지','적용일시'],msgRows)+'</div></div></div><div class="dash-bottom">'+miniBoard('newbus','신차출고요청 게시판')+miniBoard('maintenance','유지보수 신청 내역')+miniBoard('notice','공지사항')+'</div>';
}
function loginView(){closeModal();const overlay=document.createElement('div');overlay.className='login-page';overlay.innerHTML='<form class="login-card"><img src="assets/busan-association.png" alt="부산광역시버스운송사업조합"><input name="username" value="admin" aria-label="아이디" autocomplete="username"><input type="password" name="password" aria-label="비밀번호" placeholder="검토용 비밀번호" autocomplete="current-password"><button type="submit">검토용 로그인</button><p class="hint">화면 검토용 로그인입니다.<br>실제 계정 인증은 서버 연동 후 사용할 수 있습니다.</p></form>';document.body.append(overlay);overlay.querySelector('form').onsubmit=e=>{e.preventDefault();if(!overlay.querySelector('[name=username]').value.trim())return;overlay.remove();routeTo('dashboard');};}
document.addEventListener('click',async e=>{
 const nav=e.target.closest('.nav-children a');if(nav){e.preventDefault();routeTo(nav.getAttribute('href').slice(1));return;}
 const b=e.target.closest('[data-action]');if(!b)return;try{const a=b.dataset.action;
 switch(a){
 case 'home':routeTo('dashboard');break;
 case 'navigate':routeTo(b.dataset.target);break;
 case 'nav-toggle':{const id=b.dataset.id;openGroups.has(id)?openGroups.delete(id):openGroups.add(id);// Keep edited inputs when toggling navigation.
 const group=b.closest('.nav-group');const menu=menus.find(m=>m.id===id);b.setAttribute('aria-expanded',String(openGroups.has(id)));b.lastElementChild.textContent=openGroups.has(id)?'⌃':'⌄';$('.nav-children',group)?.remove();if(openGroups.has(id)){const children=document.createElement('div');children.className='nav-children';children.innerHTML=menu.items.map(([key,label])=>'<a href="#'+key+'"'+(key===currentPage?' class="selected" aria-current="page"':'')+'>'+label+'</a>').join('');group.append(children);}break;}
 case 'mobile-menu':$('.sidebar').classList.toggle('mobile-open');break;
 case 'logout':loginView();break;
 case 'close-modal':closeModal();break;
 case 'page':tablePage=Number(b.dataset.page);renderContent();break;
 case 'group-preview':selectedFile=b.dataset.file;previewInto(selectedFile);break;
 case 'apply-bulk':applySettings(b.dataset.kind,b.dataset.scope,true);break;
 case 'apply-rows':applySettings(b.dataset.kind,b.dataset.scope,false);break;
 case 'file-register':await registerFile(b.dataset.type);break;
 case 'file-detail':await fileDetail(b.dataset.id);break;
 case 'file-download':await downloadFile(b.dataset.id);break;
 case 'file-delete':deleteFile(b.dataset.id);break;
 case 'bus-add':addBus(false);break;
 case 'bus-copy':addBus(true);break;
 case 'bus-column':addBusColumn();break;
 case 'bus-delete':deleteBus(b.dataset.id);break;
 case 'bus-save':saveBus();break;
 case 'bus-import':$('#import-input').value='';$('#import-input').click();break;
 case 'bus-export':ExcelIO.download(await ExcelIO.blob(busDraft.columns,busDraft.rows),busDraft.title+'.xlsx');break;
 case 'device-bulk':applyDevices(true);break;
 case 'device-apply':applyDevices(false);break;
 case 'device-delete':confirmBox('단말기 삭제','선택한 단말기 등록정보를 삭제하시겠습니까?',()=>{state.devices=state.devices.filter(d=>d.id!==b.dataset.id);delete state.firmwareSettings[b.dataset.id];persist();renderContent();toast('단말기를 삭제했습니다.');},'삭제');break;
 case 'device-export':{const cols=['운수사','차량번호','단말기위치','노선번호','펌웨어실제버전','펌웨어현재버전','펌웨어미래버전','미래버전적용일시','업데이트시간','MAC'];const rows=deviceRows().map(d=>{const bus=state.buses.find(x=>x.id===d.busId),v=state.firmwareSettings[d.id];return Object.fromEntries(cols.map((c,i)=>[c,[bus['운수사'],bus['차량번호'],d.position,bus['인가노선'],fname(d.actual),fname(v?.current),v?.future?fname(v.future):'',v?.at||'',d.last,d.mac][i]]));});ExcelIO.download(await ExcelIO.blob(cols,rows),'단말기_상태정보.xlsx');break;}
 case 'post-new':postForm(b.dataset.board);break;
 case 'post-detail':postDetail(b.dataset.board,b.dataset.id);break;
 case 'post-edit':postForm(b.dataset.board,b.dataset.id);break;
 case 'post-download':{const blob=await blobGet('post-'+b.dataset.id);if(!blob)throw Error('첨부파일이 없습니다.');ExcelIO.download(blob,b.dataset.name);break;}
 case 'master-edit':masterForm(b.dataset.type,b.dataset.id);break;
 case 'master-delete':{const ids=$$('[data-master-check]:checked').map(x=>x.dataset.masterCheck);if(!ids.length)throw Error('삭제할 항목을 선택해 주세요.');const type=b.dataset.type;if(type==='companies'){const names=state.companies.filter(x=>ids.includes(x.id)).map(x=>x.name);if(state.buses.some(bus=>names.includes(bus['운수사']))||state.users.some(u=>names.includes(u.company)))throw Error('차량 또는 사용자에 연결된 운수사는 삭제할 수 없습니다.');}if(type==='users'&&state.users.some(u=>ids.includes(u.id)&&u.login==='admin'))throw Error('기본 관리자 계정은 삭제할 수 없습니다.');confirmBox('선택 항목 삭제',ids.length+'개 항목을 삭제하시겠습니까?',()=>{state[type]=state[type].filter(x=>!ids.includes(x.id));persist();renderContent();toast('선택한 항목을 삭제했습니다.');},'삭제');break;}
 }
 }catch(error){formError(error);}
});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='page-search'){query=t.value;tablePage=1;redrawWithFocus();}else if(t.hasAttribute('data-bus-column')){const row=busDraft.rows.find(r=>r.id===t.closest('tr').dataset.busId);if(row){row[t.dataset.busColumn]=t.value;markBusDirty();}}else if(t.id==='bus-version-name'){busDraft.title=t.value;markBusDirty();}else if(t.hasAttribute('data-field')&&t.closest('tr'))t.closest('tr').dataset.dirty='true';});
document.addEventListener('change',e=>{const t=e.target;try{
 if(t.hasAttribute('data-field')&&t.closest('tr')){t.closest('tr').dataset.dirty='true';if(['current','future','message'].includes(t.dataset.field)&&file(t.value)){selectedFile=t.value;previewInto(selectedFile);}}
 if(t.id==='bulk-message'||t.id==='bulk-current'||t.id==='bulk-future'){if(file(t.value)){selectedFile=t.value;previewInto(selectedFile);}}
 if(t.name==='bus-row'){busSelected=t.value;$$('tr[data-bus-id]').forEach(tr=>tr.classList.toggle('selected',tr.dataset.busId===busSelected));}
 if(t.hasAttribute('data-bus-column')){const row=busDraft.rows.find(r=>r.id===t.closest('tr').dataset.busId);if(row){row[t.dataset.busColumn]=t.value;markBusDirty();}}
 if(t.id==='bus-version')changeBusVersion(t.value);
 if(t.id==='files-all'){$$('[data-file-check]').forEach(el=>{el.checked=t.checked;t.checked?selectedFiles.add(el.dataset.fileCheck):selectedFiles.delete(el.dataset.fileCheck);});}
 if(t.hasAttribute('data-file-check')){t.checked?selectedFiles.add(t.dataset.fileCheck):selectedFiles.delete(t.dataset.fileCheck);const all=$$('[data-file-check]');if($('#files-all')){$('#files-all').checked=all.length>0&&all.every(x=>x.checked);$('#files-all').indeterminate=all.some(x=>x.checked)&&!all.every(x=>x.checked);}}
 if($('#selected-files-count'))$('#selected-files-count').textContent='선택 '+selectedFiles.size+'건';
 if(t.id==='master-all')$$('[data-master-check]').forEach(el=>el.checked=t.checked);
 }catch(error){formError(error);}});
$('#import-input').addEventListener('change',async e=>{try{await importBuses(e.target.files[0]);}catch(error){formError(error);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.modal'))closeModal();if(e.key==='Tab'&&$('.modal')){const nodes=$$('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]',$('.modal')).filter(el=>el.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();query='';tablePage=1;selectedFiles.clear();selectedFile='';if(currentPage==='bus-info'&&!busDirty)busDraft=null;renderShell();});
window.addEventListener('beforeunload',e=>{if(busDirty){e.preventDefault();e.returnValue='';}});
setInterval(updateClock,1000);renderShell();
})();
